action.code:
if (lfs->lookahead_block != LFS_BLOCK_INVALID) {
    *block = lfs->lookahead_block;
    lfs->lookahead_block = LFS_BLOCK_INVALID;
    return LFS_ERR_OK;
}

lfs_block_t best_block = LFS_BLOCK_INVALID;
uint32_t min_wear = 0xFFFFFFFF;

for (lfs_block_t b = 0; b < lfs->block_count; b++) {
    if (lfs->is_free(b)) {
        uint32_t wear = lfs->get_wear(b);
        if (best_block == LFS_BLOCK_INVALID || wear < min_wear) {
            min_wear = wear;
            best_block = b;
        }
    }
}

if (best_block == LFS_BLOCK_INVALID) {
    return LFS_ERR_NOSPC;
}

*block = best_block;
return LFS_ERR_OK;

